#[derive(Debug, Error)]
enum CliError {
    #[error("{0}")]
    Usage(String),
    #[error("{0}")]
    SupervisorLeaseLost(String),
    #[error("store error: {0}")]
    Store(#[from] harness_store::StoreError),
    #[error("io error: {0}")]
    Io(#[from] std::io::Error),
    #[error("json error: {0}")]
    Json(#[from] serde_json::Error),
}

type CliResult<T> = Result<T, CliError>;

impl CliError {
    fn is_supervisor_lease_lost(&self) -> bool {
        matches!(self, Self::SupervisorLeaseLost(_))
    }

    fn is_provider_compatibility_blocked(&self) -> bool {
        matches!(self, Self::Usage(message) if message.starts_with("PROVIDER_COMPATIBILITY_BLOCKED:"))
    }
}

/// Whether a routed message is currently actionable as a manual acknowledgement.
///
/// The compatibility `unacked_messages` projection deliberately excludes queued,
/// injected, failed, expired, and already-acknowledged deliveries. A message is
/// counted once when at least one recipient has a `manual_ack` delivery that has
/// reached `delivered`.
pub(crate) fn has_actionable_delivered_manual_ack(message: &TeamMessage) -> bool {
    message.deliveries.iter().any(|delivery| {
        delivery.policy == TeamDeliveryPolicy::ManualAck
            && delivery.status == TeamDeliveryStatus::Delivered
    })
}

fn store_conflict_as_usage<T>(result: Result<T, StoreError>) -> CliResult<T> {
    match result {
        Ok(value) => Ok(value),
        Err(StoreError::Conflict(message)) => Err(CliError::Usage(message)),
        Err(error) => Err(CliError::Store(error)),
    }
}

fn main() {
    if let Err(error) = run() {
        eprintln!("error: {error}");
        std::process::exit(1);
    }
}

/// How the active store root was chosen — surfaced via the `--store-source` debug
/// flag and used to keep back-compat behavior auditable (goal-multi-project P1/P7).
#[derive(Debug, Clone, PartialEq, Eq)]
enum StoreSource {
    /// `--store <path>` override (deprecated, kept for tests/back-compat).
    StoreFlag,
    /// Internal guard for workflow child processes. A workflow leaf may run with
    /// full provider permissions, so nested `harness ...` commands default to a
    /// session-local store unless the operator explicitly opts out.
    WorkflowChildEnv,
    /// `HARNESS_ROOT` env override (deprecated, kept for tests/back-compat).
    HarnessRootEnv,
    /// `--company <id>` explicit Company Store selector. Only applies to
    /// `harness company ...` commands.
    CompanyFlag,
    /// `HARNESS_COMPANY` Company Store selector. Only applies to
    /// `harness company ...` commands.
    CompanyEnv,
    /// Active Company Store marker / registry current. Only applies to
    /// `harness company ...` commands.
    CompanyCurrent,
    /// `--space <id>` explicit Execution Space selector.
    SpaceFlag,
    /// `HARNESS_SPACE` Execution Space selector.
    SpaceEnv,
    /// Active Execution Space marker / registry current.
    SpaceCurrent,
    /// `--project <id|path>` explicit selector.
    ProjectFlag,
    /// `HARNESS_PROJECT` env selector.
    ProjectEnv,
    /// Registry `current_project_id` / `ACTIVE_PROJECT` marker.
    RegistryCurrent,
    /// Legacy cwd walk-up to the nearest existing `.harness/` (deprecation-warned).
    CwdWalkUp,
    /// Reserved GLOBAL project (`$HOME`), auto-created on first use.
    GlobalDefault,
}

/// The resolved coordination store plus its independent execution bindings.
///
/// `execution_space_context` owns Mission/Wave/Agent Team/Workflow rows.
/// `context` is the selected Project Binding compatibility adapter and owns
/// provider cwd, repository instructions, Skills, Git/worktree and permission
/// boundaries. Neither identity implies the other.
pub(crate) struct ResolvedStore {
    root: PathBuf,
    source: StoreSource,
    pub(crate) context: Option<harness_core::ProjectContext>,
    pub(crate) company_context: Option<company_store::CompanyContext>,
    pub(crate) execution_space_context: Option<ExecutionSpace>,
}

/// Resolve the Harness coordination store and Project Binding.
///
/// Store precedence:
/// 1. `--store` / workflow-child store / `HARNESS_ROOT` compatibility override.
/// 2. Company Store selector for `harness company ...`.
/// 3. `--space` / `HARNESS_SPACE` / active Execution Space.
/// 4. project-derived compatibility store only when no Execution Space exists.
/// 5. legacy repo-local `.harness`, then active/global compatibility project.
///
/// Project Binding precedence is independent:
/// `--project` / `HARNESS_PROJECT`, then the selected space's default binding,
/// then the active Project Binding. Selecting it never switches the store.
///
/// `init` is special-cased so it never adopts an ancestor's `.harness` via the
/// walk-up; its routing lives in [`init_routed`].
///
/// IMPORTANT back-compat: when NONE of the project signals (3/4/5) and NO
/// override (1/2) apply, the result is the SAME directory today's code would have
/// used (walk-up → otherwise the GLOBAL store), so existing serve + run-script
/// flows keep converging on one store.
fn resolve_store(args: &mut Vec<String>, command: Option<&str>) -> CliResult<ResolvedStore> {
    // Raw store overrides remain the highest-precedence compatibility path.
    if let Some(path) = take_flag_value(args, "--store") {
        warn_deprecated_override("--store", "harness space switch");
        return Ok(ResolvedStore {
            root: PathBuf::from(path),
            source: StoreSource::StoreFlag,
            context: None,
            company_context: None,
            execution_space_context: None,
        });
    }
    if let Ok(root) = env::var(HARNESS_WORKFLOW_CHILD_STORE_ROOT_ENV) {
        if !root.is_empty() {
            return Ok(ResolvedStore {
                root: PathBuf::from(root),
                source: StoreSource::WorkflowChildEnv,
                context: None,
                company_context: None,
                execution_space_context: None,
            });
        }
    }
    if let Ok(root) = env::var("HARNESS_ROOT") {
        if !root.is_empty() {
            warn_deprecated_override("HARNESS_ROOT", "harness space switch");
            return Ok(ResolvedStore {
                root: PathBuf::from(root),
                source: StoreSource::HarnessRootEnv,
                context: None,
                company_context: None,
                execution_space_context: None,
            });
        }
    }

    let harness_home = match project::harness_home() {
        Ok(h) => h,
        // No HOME: fall back to the historical `./.harness` so we never panic.
        Err(_) => {
            return Ok(ResolvedStore {
                root: PathBuf::from(".harness"),
                source: StoreSource::CwdWalkUp,
                context: None,
                company_context: None,
                execution_space_context: None,
            });
        }
    };

    if command == Some("company") {
        let (company_selector, selector_source) = match take_flag_value(args, "--company") {
            Some(v) => (Some(v), StoreSource::CompanyFlag),
            None => match env::var("HARNESS_COMPANY").ok().filter(|s| !s.is_empty()) {
                Some(v) => (Some(v), StoreSource::CompanyEnv),
                None => (None, StoreSource::CompanyFlag),
            },
        };
        if let Some(selector) = company_selector {
            let ctx = company_store::context_for_id(&harness_home, &selector)
                .map_err(company_store_err)?
                .ok_or_else(|| CliError::Usage(format!("unknown company: {selector}")))?;
            return Ok(ResolvedStore {
                root: ctx.store_root.clone(),
                source: selector_source,
                context: None,
                company_context: Some(ctx),
                execution_space_context: None,
            });
        }
        if let Some(id) =
            company_store::active_company_id(&harness_home).map_err(company_store_err)?
        {
            let ctx = company_store::context_for_id(&harness_home, &id)
                .map_err(company_store_err)?
                .ok_or_else(|| CliError::Usage(format!("active company is unknown: {id}")))?;
            return Ok(ResolvedStore {
                root: ctx.store_root.clone(),
                source: StoreSource::CompanyCurrent,
                context: None,
                company_context: Some(ctx),
                execution_space_context: None,
            });
        }
    }

    // Project selection is now independent from execution-store selection. It
    // picks the provider workspace/config/permission binding only.
    let (project_selector, selector_source) = match take_flag_value(args, "--project") {
        Some(v) => (Some(v), StoreSource::ProjectFlag),
        None => match env::var("HARNESS_PROJECT").ok().filter(|s| !s.is_empty()) {
            Some(v) => (Some(v), StoreSource::ProjectEnv),
            None => (None, StoreSource::ProjectFlag),
        },
    };
    let explicit_project_context = match project_selector.as_deref() {
        Some(selector) => Some(
            resolve_project_selector(&harness_home, selector)
                .ok_or_else(|| CliError::Usage(format!("unknown project binding: {selector}")))?,
        ),
        None => None,
    };

    // Company OS compatibility rows must never fall through into an Execution
    // Space. Until a native Company Store is selected, retain the historical
    // project-derived Company OS store as a narrow compatibility boundary.
    if command == Some("company") {
        let (context, source) = match explicit_project_context {
            Some(context) => (context, selector_source),
            None => match project::active_project_id(&harness_home).map_err(project_err)? {
                Some(id) => (
                    project::context_for_id(&harness_home, &id)
                        .map_err(project_err)?
                        .ok_or_else(|| {
                            CliError::Usage(format!("active project binding is unknown: {id}"))
                        })?,
                    StoreSource::RegistryCurrent,
                ),
                None => (
                    project::global_context(&harness_home).map_err(project_err)?,
                    StoreSource::GlobalDefault,
                ),
            },
        };
        return Ok(ResolvedStore {
            root: context.store_root.clone(),
            source,
            context: Some(context),
            company_context: None,
            execution_space_context: None,
        });
    }

    // Execution Space owns Mission/Wave/Agent Team/Workflow coordination.
    // Selecting a Project Binding never changes this store.
    let (space_selector, space_source) = match take_flag_value(args, "--space") {
        Some(value) => (Some(value), StoreSource::SpaceFlag),
        None => match env::var("HARNESS_SPACE")
            .ok()
            .filter(|value| !value.is_empty())
        {
            Some(value) => (Some(value), StoreSource::SpaceEnv),
            None => (
                execution_space::active_space_id(&harness_home).map_err(execution_space_err)?,
                StoreSource::SpaceCurrent,
            ),
        },
    };
    if let Some(space_id) = space_selector {
        let space = execution_space::context_for_id(&harness_home, &space_id)
            .map_err(execution_space_err)?
            .ok_or_else(|| CliError::Usage(format!("unknown execution space: {space_id}")))?;
        let project_context = match explicit_project_context {
            Some(context) => Some(context),
            None => match space.default_project_binding_id.as_deref() {
                Some(binding_id) => {
                    project::context_for_id(&harness_home, binding_id).map_err(project_err)?
                }
                None => project::active_project_id(&harness_home)
                    .map_err(project_err)?
                    .and_then(|id| project::context_for_id(&harness_home, &id).ok().flatten()),
            },
        };
        return Ok(ResolvedStore {
            root: space.store_root.clone(),
            source: space_source,
            context: project_context,
            company_context: None,
            execution_space_context: Some(space),
        });
    }

    // No Execution Space was selected yet: preserve the old project-derived
    // compatibility store without silently migrating or dual-writing history.
    if let Some(context) = explicit_project_context {
        return Ok(ResolvedStore {
            root: context.store_root.clone(),
            source: selector_source,
            context: Some(context),
            company_context: None,
            execution_space_context: None,
        });
    }

    // 5. Legacy cwd walk-up to the nearest existing `.harness/` (back-compat).
    // A PRESENT repo-local `.harness` WINS over the registry-current project
    // (rung 6): this restores the design's stated invariant that, absent an
    // explicit project signal, resolution lands on the SAME store today's code
    // would use — so standing inside a legacy repo never silently shadows its
    // local goals/tasks with an unrelated active project. (`init` never walks up
    // — it materializes a fresh store, see `init_routed`.)
    //
    // DUAL-READ (goal-multi-project P7): central (steps 3/4/5) was absent, so we may
    // fall back to a repo-local store — but ONLY if it has not been migrated. A local
    // store carrying a `MIGRATED_TO_CENTRAL` marker is redirected to the central
    // store it points to (never serving stale rows), and the choice is always logged.
    if command != Some("init") {
        if let Ok(cwd) = env::current_dir() {
            // A walked-up `.harness` that IS the central harness home (e.g.
            // `~/.harness`, which holds `projects/` + `registry.json`) is the
            // container for project stores, NOT a legacy repo-local store — skip it
            // so resolution falls through to the registry-current project (issue #89
            // convergence holds for cwds inside the home tree).
            let found = discover_harness_from(&cwd).filter(|p| {
                project::canonicalize_best_effort(p)
                    != project::canonicalize_best_effort(&harness_home)
            });
            if let Some(found) = found {
                match project::read_migrated_marker(&found) {
                    Ok(Some(target)) if !target.as_os_str().is_empty() => {
                        // Migrated: prefer the central store the marker points to.
                        eprintln!(
                            "store-source: local store {} is migrated; reading central store {}",
                            found.display(),
                            target.display()
                        );
                        let context = project::read_metadata(&target).ok().flatten().map(|meta| {
                            harness_core::ProjectContext {
                                id: meta.project_id,
                                project_root: meta.canonical_path,
                                store_root: target.clone(),
                                kind: meta.kind,
                                is_git_repo: meta.is_git_repo,
                            }
                        });
                        return Ok(ResolvedStore {
                            root: target,
                            source: StoreSource::RegistryCurrent,
                            context,
                            company_context: None,
                            execution_space_context: None,
                        });
                    }
                    Ok(Some(_)) => {
                        // Marked migrated but pointer-less: ignore the local store and
                        // fall through to registry-current / the GLOBAL default
                        // rather than serve it.
                        eprintln!(
                            "store-source: local store {} is marked migrated (no target); \
                             skipping it for the active/global project",
                            found.display()
                        );
                    }
                    _ => {
                        // Unmigrated local store: keep working, but warn it is a
                        // back-compat fallback (no central project selected).
                        eprintln!(
                            "warning: using repo-local store {} (no central project selected); \
                             run `harness project migrate` to centralize it",
                            found.display()
                        );
                        warn_deprecated_override(
                            "cwd .harness walk-up",
                            "harness init / harness project switch",
                        );
                        return Ok(ResolvedStore {
                            root: found,
                            source: StoreSource::CwdWalkUp,
                            context: None,
                            company_context: None,
                            execution_space_context: None,
                        });
                    }
                }
            }
        }
    }

    // 6. Registry current project (the cwd-independent convergence point) — the
    // resolver for project roots with NO repo-local `.harness` (e.g. a centrally
    // `init`ed project) and the cross-cwd convergence point (issue #89).
    if let Ok(Some(id)) = project::active_project_id(&harness_home) {
        if let Ok(Some(ctx)) = project::context_for_id(&harness_home, &id) {
            return Ok(ResolvedStore {
                root: ctx.store_root.clone(),
                source: StoreSource::RegistryCurrent,
                context: Some(ctx),
                company_context: None,
                execution_space_context: None,
            });
        }
    }

    // 7. Reserved GLOBAL project, auto-created on first use.
    if let Ok(ctx) = project::global_context(&harness_home) {
        return Ok(ResolvedStore {
            root: ctx.store_root.clone(),
            source: StoreSource::GlobalDefault,
            context: Some(ctx),
            company_context: None,
            execution_space_context: None,
        });
    }

    // Absolute last resort (no HOME / global failed): historical default.
    Ok(ResolvedStore {
        root: PathBuf::from(".harness"),
        source: StoreSource::CwdWalkUp,
        context: None,
        company_context: None,
        execution_space_context: None,
    })
}

/// Resolve a `--project`/`HARNESS_PROJECT` selector that may be a registered id OR
/// a path to a project root. Returns `None` if it cannot be resolved (caller then
/// continues down the precedence chain).
fn resolve_project_selector(
    harness_home: &Path,
    selector: &str,
) -> Option<harness_core::ProjectContext> {
    // First: treat as a known id (registry / metadata / reserved `_global`).
    if let Ok(Some(ctx)) = project::context_for_id(harness_home, selector) {
        return Some(ctx);
    }
    // Otherwise: treat as a path to a project root and derive its identity.
    let candidate = Path::new(selector);
    if candidate.exists() {
        let canonical = project::canonicalize_best_effort(candidate);
        // Prefer a registered entry pinned to this canonical path (keeps a pinned
        // store_root even if path→id derivation later changes).
        if let Ok(registry) = project::ProjectRegistry::load(harness_home) {
            if let Some(entry) = registry.find_by_path(&canonical) {
                if let Ok(Some(ctx)) = project::context_for_id(harness_home, &entry.id) {
                    return Some(ctx);
                }
            }
        }
        if let Ok(ctx) = project::context_for_root(candidate, harness_home) {
            return Some(ctx);
        }
    }
    None
}

/// Emit a one-line deprecation warning for a legacy store-selection mechanism,
/// pointing at the supported replacement. Routed to stderr so it never corrupts
/// JSON stdout.
fn warn_deprecated_override(what: &str, replacement: &str) {
    eprintln!("warning: {what} is deprecated for store selection; prefer `{replacement}`");
}

/// Back-compat shim: callers that only need the store root keep working. New code
/// should use [`resolve_store`] to also get the `StoreSource`/`ProjectContext`.
/// Only used by tests today; `run()` calls [`resolve_store`] directly.
#[cfg(test)]
fn resolve_store_root(args: &mut Vec<String>) -> PathBuf {
    let command = args.first().cloned();
    resolve_store(args, command.as_deref())
        .expect("resolve store")
        .root
}

/// Walk up from `start` returning the first existing `<dir>/.harness` directory,
/// or `None` if none is found up to the filesystem root.
fn discover_harness_from(start: &Path) -> Option<PathBuf> {
    let mut dir = start.to_path_buf();
    loop {
        let candidate = dir.join(".harness");
        if candidate.is_dir() {
            return Some(candidate);
        }
        if !dir.pop() {
            return None;
        }
    }
}

/// Remove the first `--flag <value>` pair from `args`, returning the value. The
/// flag is always removed; the value is returned only when present (a trailing
/// `--flag` with no value yields `None`).
fn take_flag_value(args: &mut Vec<String>, flag: &str) -> Option<String> {
    let pos = args.iter().position(|a| a == flag)?;
    args.remove(pos);
    if pos < args.len() {
        Some(args.remove(pos))
    } else {
        None
    }
}

/// Remove a boolean `--flag` from `args`, returning whether it was present.
fn take_flag(args: &mut Vec<String>, flag: &str) -> bool {
    if let Some(pos) = args.iter().position(|a| a == flag) {
        args.remove(pos);
        true
    } else {
        false
    }
}

fn command_name_for_resolution(args: &[String]) -> Option<String> {
    let mut index = 0usize;
    while index < args.len() {
        match args[index].as_str() {
            "--store" | "--project" | "--company" | "--space" => {
                index += 2;
            }
            "--store-source" => {
                index += 1;
            }
            value if value.starts_with("--") => {
                index += 1;
            }
            value => return Some(value.to_string()),
        }
    }
    None
}

/// `harness init` routing (goal-multi-project init-routing task).
///
/// Instead of blindly materializing `./.harness`, `init` registers the SELECTED
/// project in the centralized registry and creates its store under
/// `~/.harness/projects/<id>/`, writing `metadata.json` to pin identity and the
/// `ACTIVE_PROJECT` marker so subsequent commands converge.
///
/// Which project is initialized:
/// - `--store`/`HARNESS_ROOT` override → that raw path is materialized exactly as
///   before (no registry entry), so compatibility tests keep passing.
/// - `--project <id|path>`             → the explicitly selected project root.
/// - otherwise                         → the CURRENT DIRECTORY (the dir the user
///   ran `init` in), NOT `_global` and NOT an ancestor's local `.harness`. This
///   preserves the historical "init targets here" intent while routing the store
///   centrally. The key invariant — never silently adopt an ancestor's local
///   `.harness` as the canonical store — holds because `resolve_store` skips the
///   cwd walk-up for `init`.
fn init_routed(store: &HarnessStore, resolved: &ResolvedStore) -> CliResult<()> {
    // Override path (`--store`/`HARNESS_ROOT`): historical raw-path behavior.
    if matches!(
        resolved.source,
        StoreSource::StoreFlag | StoreSource::WorkflowChildEnv | StoreSource::HarnessRootEnv
    ) {
        store.init()?;
        println!("initialized {}", store.root().display());
        return Ok(());
    }

    let harness_home = project::harness_home().map_err(project_err)?;
    // An explicit `--project`/`HARNESS_PROJECT` selector pins the root via the
    // resolved context; otherwise `init` materializes the CURRENT directory as a
    // project (never the GLOBAL default, never an ancestor's `.harness`).
    let project_root = match resolved.source {
        StoreSource::ProjectFlag | StoreSource::ProjectEnv => resolved
            .context
            .as_ref()
            .map(|c| c.project_root.clone())
            .unwrap_or_else(|| env::current_dir().unwrap_or_else(|_| PathBuf::from("."))),
        _ => env::current_dir().unwrap_or_else(|_| PathBuf::from(".")),
    };
    let ctx = project::register_and_activate(&harness_home, &project_root, &now_string())
        .map_err(project_err)?;
    let registered = HarnessStore::new(ctx.store_root.clone());
    registered.init()?;
    let existing_execution_rows = EXECUTION_LEDGER_NAMES
        .iter()
        .map(|ledger| count_non_empty_lines(&ctx.store_root.join(ledger)).unwrap_or(0))
        .sum::<u64>();
    if execution_space::active_space_id(&harness_home)
        .map_err(execution_space_err)?
        .is_none()
        && existing_execution_rows == 0
    {
        let space = execution_space::register_and_activate(
            &harness_home,
            &ctx.id,
            &format!("{} execution", ctx.id),
            Some(ctx.id.clone()),
            None,
            &now_string(),
        )
        .map_err(execution_space_err)?;
        HarnessStore::new(space.store_root.clone()).init()?;
        println!(
            "initialized project binding {} (root {}) and execution space {} ({})",
            ctx.id,
            ctx.project_root.display(),
            space.id,
            space.store_root.display()
        );
    } else {
        println!(
            "initialized project binding {} (root {}); compatibility store {} retained",
            ctx.id,
            ctx.project_root.display(),
            ctx.store_root.display()
        );
        if existing_execution_rows > 0 {
            eprintln!(
                "note: existing project-scoped execution rows were not moved; run `harness space migrate-from-project --from-project {} --id <space-id>` explicitly",
                ctx.id
            );
        }
    }
    Ok(())
}

/// Map a `project::ProjectError` onto `CliError` at the command boundary.
fn project_err(e: project::ProjectError) -> CliError {
    match e {
        project::ProjectError::Io(io) => CliError::Io(io),
        project::ProjectError::Json(j) => CliError::Json(j),
        project::ProjectError::NoHome => {
            CliError::Usage("could not determine home directory".to_string())
        }
    }
}

/// Map a `company_store::CompanyStoreError` onto `CliError` at the command
/// boundary.
fn company_store_err(e: company_store::CompanyStoreError) -> CliError {
    match e {
        company_store::CompanyStoreError::Io(io) => CliError::Io(io),
        company_store::CompanyStoreError::Json(j) => CliError::Json(j),
        company_store::CompanyStoreError::InvalidId(msg) => CliError::Usage(format!(
            "invalid company id `{msg}`; use letters, digits, '.', '_' or '-'"
        )),
        company_store::CompanyStoreError::NoHome => {
            CliError::Usage("could not determine harness home".to_string())
        }
    }
}

fn execution_space_err(error: execution_space::ExecutionSpaceError) -> CliError {
    match error {
        execution_space::ExecutionSpaceError::Io(error) => CliError::Io(error),
        execution_space::ExecutionSpaceError::Json(error) => CliError::Json(error),
        execution_space::ExecutionSpaceError::InvalidId(id) => CliError::Usage(format!(
            "invalid execution space id `{id}`; use letters, digits, '.', '_' or '-'"
        )),
        execution_space::ExecutionSpaceError::NoHome => {
            CliError::Usage("could not determine harness home".to_string())
        }
    }
}

fn execution_space_json(space: &ExecutionSpace, current: &str) -> serde_json::Value {
    serde_json::json!({
        "id": space.id,
        "name": space.name,
        "store_root": space.store_root.display().to_string(),
        "default_project_binding_id": space.default_project_binding_id,
        "company_id": space.company_id,
        "is_current": space.id == current,
        "identity_boundary": "execution_space",
        "owns": ["mission", "wave", "agent_team", "team_run", "member_run", "team_message", "workflow"],
    })
}

fn execution_space_command(args: &[String]) -> CliResult<()> {
    require_subcommand(
        args,
        "space init|list|current|switch|show|migrate-from-project",
    )?;
    let harness_home = execution_space::harness_home().map_err(execution_space_err)?;
    match args[0].as_str() {
        "init" => {
            let id = required(args, "--id")?;
            let name = value(args, "--name").unwrap_or_else(|| id.clone());
            let default_project_binding_id = value(args, "--project-binding");
            if let Some(binding) = default_project_binding_id.as_deref() {
                if project::binding_for_id(&harness_home, binding)
                    .map_err(project_err)?
                    .is_none()
                {
                    return Err(CliError::Usage(format!(
                        "unknown project binding: {binding}"
                    )));
                }
            }
            let company_id = value(args, "--company");
            if let Some(company) = company_id.as_deref() {
                if company_store::context_for_id(&harness_home, company)
                    .map_err(company_store_err)?
                    .is_none()
                {
                    return Err(CliError::Usage(format!("unknown company: {company}")));
                }
            }
            let context = execution_space::register_and_activate(
                &harness_home,
                &id,
                &name,
                default_project_binding_id,
                company_id,
                &now_string(),
            )
            .map_err(execution_space_err)?;
            HarnessStore::new(context.store_root.clone()).init()?;
            print_json(&execution_space_json(&context, &context.id))
        }
        "list" => {
            let current = execution_space::active_space_id(&harness_home)
                .map_err(execution_space_err)?
                .unwrap_or_default();
            let spaces =
                execution_space::list_spaces(&harness_home).map_err(execution_space_err)?;
            print_json(
                &spaces
                    .iter()
                    .map(|space| execution_space_json(space, &current))
                    .collect::<Vec<_>>(),
            )
        }
        "current" => {
            let current =
                execution_space::active_space_id(&harness_home).map_err(execution_space_err)?;
            match current {
                Some(id) => match execution_space::context_for_id(&harness_home, &id)
                    .map_err(execution_space_err)?
                {
                    Some(space) => print_json(&execution_space_json(&space, &id)),
                    None => print_json(&serde_json::json!({"id": id, "is_current": true})),
                },
                None => print_json(
                    &serde_json::json!({"id": serde_json::Value::Null, "is_current": false}),
                ),
            }
        }
        "switch" => {
            let id = args
                .iter()
                .skip(1)
                .find(|value| !value.starts_with("--"))
                .ok_or_else(|| CliError::Usage("usage: harness space switch <id>".into()))?;
            let space = execution_space::switch_current_space(&harness_home, id, &now_string())
                .map_err(execution_space_err)?;
            print_json(&execution_space_json(&space, &space.id))
        }
        "show" => {
            let selector = args
                .iter()
                .skip(1)
                .find(|value| !value.starts_with("--"))
                .cloned()
                .or(execution_space::active_space_id(&harness_home).map_err(execution_space_err)?)
                .ok_or_else(|| CliError::Usage("no active execution space".into()))?;
            let current = execution_space::active_space_id(&harness_home)
                .map_err(execution_space_err)?
                .unwrap_or_default();
            let space = execution_space::context_for_id(&harness_home, &selector)
                .map_err(execution_space_err)?
                .ok_or_else(|| CliError::Usage(format!("unknown execution space: {selector}")))?;
            print_json(&execution_space_json(&space, &current))
        }
        "migrate-from-project" => execution_space_migrate_from_project(&harness_home, &args[1..]),
        other => Err(CliError::Usage(format!("unknown space command: {other}"))),
    }
}

const EXECUTION_LEDGER_NAMES: &[&str] = &[
    "missions.jsonl",
    "waves.jsonl",
    "members.jsonl",
    "durable_agent_members.jsonl",
    "teams.jsonl",
    "agent_runtimes.jsonl",
    "agent_events.jsonl",
    "proposals.jsonl",
    "messages.jsonl",
    "agent_message_routes.jsonl",
    "evidence.jsonl",
    "decisions.jsonl",
    "reviews.jsonl",
    "gaps.jsonl",
    "provider_child_threads.jsonl",
    "team_runs.jsonl",
    "member_runs.jsonl",
    "team_messages.jsonl",
    "work_operations.jsonl",
    "work_delivery_updates.jsonl",
    "host_attentions.jsonl",
    "team_supervisor_leases.jsonl",
    "team_member_close_requests.jsonl",
    "member_actions.jsonl",
    "pending_interactions.jsonl",
    "delegation_runs.jsonl",
    "team_run_events.jsonl",
    "workflow_runs.jsonl",
    "workflow_steps.jsonl",
    "workflow_patches.jsonl",
    "workflow_artifact_manifests.jsonl",
];

fn execution_space_migrate_from_project(harness_home: &Path, args: &[String]) -> CliResult<()> {
    let project_selector = required(args, "--from-project")?;
    let id = required(args, "--id")?;
    execution_space::validate_space_id(&id).map_err(execution_space_err)?;
    let name = value(args, "--name").unwrap_or_else(|| id.clone());
    let force = has_flag(args, "--force");
    let project_context = resolve_project_selector(harness_home, &project_selector)
        .ok_or_else(|| CliError::Usage(format!("unknown project binding: {project_selector}")))?;
    let previous_active_space_id =
        execution_space::active_space_id(harness_home).map_err(execution_space_err)?;
    let target = execution_space::space_store_root(harness_home, &id);
    std::fs::create_dir_all(&target)?;

    let mut copied_files = 0u64;
    let mut copied_records = 0u64;
    for ledger in EXECUTION_LEDGER_NAMES {
        let source = project_context.store_root.join(ledger);
        if !source.is_file() {
            continue;
        }
        let destination = target.join(ledger);
        let source_bytes = std::fs::read(&source)?;
        if destination.exists() {
            let target_bytes = std::fs::read(&destination)?;
            if source_bytes == target_bytes {
                copied_records += count_non_empty_lines(&source)?;
                continue;
            }
            if !force {
                return Err(CliError::Usage(format!(
                    "target execution ledger already differs: {} (pass --force to replace execution ledgers only)",
                    destination.display()
                )));
            }
        }
        std::fs::write(&destination, &source_bytes)?;
        copied_files += 1;
        copied_records += count_non_empty_lines(&source)?;
    }
    for directory in ["checks", "compiled", "workflow-patches"] {
        let source = project_context.store_root.join(directory);
        if source.is_dir() {
            let destination = target.join(directory);
            let source_files = directory_file_index(&source)?;
            if destination.exists() {
                if directory_trees_equal(&source, &destination)? {
                    continue;
                }
                if !force {
                    return Err(CliError::Usage(format!(
                        "target execution evidence directory already differs: {} (pass --force to replace this whitelisted target directory only)",
                        destination.display()
                    )));
                }
                std::fs::remove_dir_all(&destination)?;
            }
            copy_dir_recursive(&source, &destination)?;
            copied_files += source_files.len() as u64;
        }
    }

    let context = execution_space::register_and_activate(
        harness_home,
        &id,
        &name,
        Some(project_context.id.clone()),
        None,
        &now_string(),
    )
    .map_err(execution_space_err)?;
    HarnessStore::new(context.store_root.clone()).init()?;

    let mut verified_records = 0u64;
    for ledger in EXECUTION_LEDGER_NAMES {
        let source = project_context.store_root.join(ledger);
        if !source.is_file() {
            continue;
        }
        let destination = context.store_root.join(ledger);
        if std::fs::read(&source)? != std::fs::read(&destination)? {
            return Err(CliError::Usage(format!(
                "execution migration verification failed for {ledger}"
            )));
        }
        verified_records += count_non_empty_lines(&source)?;
    }
    for directory in ["checks", "compiled", "workflow-patches"] {
        let source = project_context.store_root.join(directory);
        if source.is_dir() && !directory_trees_equal(&source, &context.store_root.join(directory))?
        {
            return Err(CliError::Usage(format!(
                "execution migration verification failed for {directory}/"
            )));
        }
    }
    let manifest = serde_json::json!({
        "kind": "project_execution_store_to_execution_space",
        "source_project_binding_id": project_context.id,
        "source_store_root": project_context.store_root.display().to_string(),
        "target_space_id": context.id,
        "target_store_root": context.store_root.display().to_string(),
        "copied_files": copied_files,
        "copied_records": copied_records,
        "verified_records": verified_records,
        "excluded_prefixes": ["company_os_", "provider-sessions", "runtimes"],
        "source_retained": true,
        "previous_active_space_id": previous_active_space_id,
        "rollback": previous_active_space_id.as_ref().map(|previous| format!("harness space switch {previous}")),
        "created_at": now_string(),
    });
    std::fs::write(
        context.store_root.join("execution_space_migration.json"),
        serde_json::to_string_pretty(&manifest)?,
    )?;
    print_json(&serde_json::json!({
        "space": execution_space_json(&context, &context.id),
        "migration": manifest,
    }))
}

/// `harness project <subcommand>` — inspect and manage Project Bindings.
///
/// A switch changes the default provider cwd/config/Skill boundary only.
/// Native coordination routing remains owned by `harness space`.
fn project_command(args: &[String]) -> CliResult<()> {
    require_subcommand(args, "project add|list|current|switch|remove|show|migrate")?;
    let harness_home = project::harness_home().map_err(project_err)?;
    match args[0].as_str() {
        "add" => project_add(&harness_home, &args[1..]),
        "list" => project_list(&harness_home),
        "current" => project_current(&harness_home),
        "switch" => project_switch_cmd(&harness_home, &args[1..]),
        "remove" => project_remove(&harness_home, &args[1..]),
        "show" => project_show(&harness_home, &args[1..]),
        "migrate" => project_migrate(&harness_home, &args[1..]),
        other => Err(CliError::Usage(format!("unknown project command: {other}"))),
    }
}

/// `harness project add [<path>] [--switch]` — register a project root (defaulting
/// to the current directory) WITHOUT changing the active project, unless `--switch`
/// is passed. Materializes the central store + `metadata.json` and a registry entry.
fn project_add(harness_home: &Path, args: &[String]) -> CliResult<()> {
    let switch = has_flag(args, "--switch");
    // First non-flag positional is an optional explicit project root.
    let path = args.iter().find(|a| !a.starts_with("--")).cloned();
    let project_root = match path {
        Some(p) => PathBuf::from(p),
        None => env::current_dir().unwrap_or_else(|_| PathBuf::from(".")),
    };
    let now = now_string();
    // `register_and_activate` materializes store + metadata + registry entry and
    // marks current. When `--switch` is NOT requested we restore the previously
    // active project so `add` is non-disruptive (inspectable before a switch).
    let prev_active = project::active_project_id(harness_home).map_err(project_err)?;
    let ctx =
        project::register_and_activate(harness_home, &project_root, &now).map_err(project_err)?;
    if !switch {
        match prev_active {
            Some(prev) if prev != ctx.id => {
                project::switch_current_project(harness_home, &prev, &now).map_err(project_err)?;
            }
            None => {
                // There was no active project before; clear the pointer so `add`
                // alone never silently flips the default away from local/_global.
                let mut registry =
                    project::ProjectRegistry::load(harness_home).map_err(project_err)?;
                registry.current_project_id = None;
                registry.save(harness_home).map_err(project_err)?;
                project::clear_active_project(harness_home).map_err(project_err)?;
            }
            _ => {}
        }
    }
    let current = project::active_project_id(harness_home)
        .map_err(project_err)?
        .unwrap_or_default();
    print_json(&project_context_json(&ctx, &current))
}

/// `harness project list` — enumerate every known project (registry + on-disk
/// stores + the reserved `_global`), marking the current one.
fn project_list(harness_home: &Path) -> CliResult<()> {
    let current = project::active_project_id(harness_home)
        .map_err(project_err)?
        .unwrap_or_default();
    let projects = project::list_projects(harness_home).map_err(project_err)?;
    let json: Vec<serde_json::Value> = projects
        .iter()
        .map(|c| project_context_json(c, &current))
        .collect();
    print_json(&json)
}

/// `harness project current` — print the currently-active project context (the
/// convergence point `serve` + CLI workers resolve), or a `null`-id placeholder if
/// none has been selected yet.
fn project_current(harness_home: &Path) -> CliResult<()> {
    match project::active_project_id(harness_home).map_err(project_err)? {
        Some(id) => match project::context_for_id(harness_home, &id).map_err(project_err)? {
            Some(ctx) => print_json(&project_context_json(&ctx, &id)),
            None => print_json(&serde_json::json!({ "id": id, "is_current": true })),
        },
        None => print_json(&serde_json::json!({
            "id": serde_json::Value::Null,
            "is_current": false,
        })),
    }
}

/// `harness project switch <id|path>` — flip the active project, updating BOTH the
/// registry `current_project_id` and the `ACTIVE_PROJECT` marker so the next CLI
/// invocation and a live `serve` converge on the same central store.
fn project_switch_cmd(harness_home: &Path, args: &[String]) -> CliResult<()> {
    let selector = args
        .first()
        .filter(|a| !a.starts_with("--"))
        .cloned()
        .ok_or_else(|| CliError::Usage("usage: harness project switch <id|path>".to_string()))?;
    // Accept either a registered id / `_global`, or a path to a project root.
    let id = match project::context_for_id(harness_home, &selector).map_err(project_err)? {
        Some(ctx) => ctx.id,
        None => match resolve_project_selector(harness_home, &selector) {
            Some(ctx) => {
                // A path that is not yet registered: register it first so the switch
                // never strands the pointer on an unknown id.
                project::register_and_activate(harness_home, &ctx.project_root, &now_string())
                    .map_err(project_err)?;
                ctx.id
            }
            None => {
                return Err(CliError::Usage(format!(
                    "unknown project: {selector} (not a registered id, path, or `_global`)"
                )))
            }
        },
    };
    let ctx =
        project::switch_current_project(harness_home, &id, &now_string()).map_err(project_err)?;
    print_json(&project_context_json(&ctx, &ctx.id))
}

/// `harness project remove <id> [--force]` — unregister a project (the on-disk
/// central store is left intact; this is a pointer operation). The reserved
/// `_global` cannot be removed. Removing the CURRENT project requires `--force` and
/// clears the active pointer so resolution falls back safely.
fn project_remove(harness_home: &Path, args: &[String]) -> CliResult<()> {
    let force = has_flag(args, "--force");
    let id = args
        .iter()
        .find(|a| !a.starts_with("--"))
        .cloned()
        .ok_or_else(|| {
            CliError::Usage("usage: harness project remove <id> [--force]".to_string())
        })?;
    let current = project::active_project_id(harness_home).map_err(project_err)?;
    if current.as_deref() == Some(id.as_str()) && !force {
        return Err(CliError::Usage(format!(
            "`{id}` is the current project; switch away first or pass --force to remove it"
        )));
    }
    let outcome = project::remove_project(harness_home, &id).map_err(project_err)?;
    if !outcome.removed {
        return Err(CliError::Usage(format!(
            "no registered project with id `{id}`"
        )));
    }
    if outcome.was_current {
        eprintln!(
            "note: removed the active project `{id}`; no project is selected now \
             (resolution falls back to the legacy walk-up / `_global`)"
        );
    }
    print_json(&serde_json::json!({
        "removed": id,
        "was_current": outcome.was_current,
    }))
}

/// `harness project show <id|path>` — print one project's resolved context. With no
/// argument, shows the current project (alias for `current`).
fn project_show(harness_home: &Path, args: &[String]) -> CliResult<()> {
    let selector = args.iter().find(|a| !a.starts_with("--")).cloned();
    let current = project::active_project_id(harness_home)
        .map_err(project_err)?
        .unwrap_or_default();
    let ctx = match selector {
        None => return project_current(harness_home),
        Some(sel) => match project::context_for_id(harness_home, &sel).map_err(project_err)? {
            Some(ctx) => ctx,
            None => resolve_project_selector(harness_home, &sel)
                .ok_or_else(|| CliError::Usage(format!("unknown project: {sel}")))?,
        },
    };
    print_json(&project_context_json(&ctx, &current))
}

/// Subdirectories of a store that hold non-JSONL payloads and must be copied
/// wholesale during migration (provider session logs, prompts, runtime files).
const STORE_PAYLOAD_DIRS: &[&str] = &["prompts", "runtimes"];

/// `harness project migrate [<local-store>] [--switch]` — move an existing
/// repo-local `.harness/` store into the centralized per-project store
/// (goal-multi-project P7 / project-migrate task).
///
/// Steps: compute the project's canonical id from the repo root (the local store's
/// PARENT dir), copy every `*.jsonl` ledger + the payload dirs into
/// `~/.harness/projects/<id>/`, write `metadata.json` with `migrated_from`, and drop
/// a `MIGRATED_TO_CENTRAL` marker in the old store pointing at the central one.
///
/// Idempotent / fail-safe: if the local store is ALREADY marked migrated it reports
/// success without recopying; if the central store already has ledger rows it
/// refuses (to avoid clobbering newer central data) unless `--force` is given.
fn project_migrate(harness_home: &Path, args: &[String]) -> CliResult<()> {
    let force = has_flag(args, "--force");
    let switch = has_flag(args, "--switch");

    // Resolve the local store dir: explicit positional, else the cwd's `.harness`.
    let positional = args.iter().find(|a| !a.starts_with("--")).cloned();
    let local_store = match positional {
        Some(p) => PathBuf::from(p),
        None => env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(".harness"),
    };
    if !local_store.is_dir() {
        return Err(CliError::Usage(format!(
            "no local store to migrate at {} (pass a path or run from a repo with ./.harness)",
            local_store.display()
        )));
    }

    // Already migrated? Report idempotently rather than recopying.
    if let Some(target) = project::read_migrated_marker(&local_store).map_err(project_err)? {
        println!(
            "already migrated: {} → {}",
            local_store.display(),
            target.display()
        );
        return Ok(());
    }

    // The project ROOT is the local store's parent (the repo dir), not the store
    // itself, so the id matches what `init`/`switch` would derive for that repo.
    let project_root = local_store
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| local_store.clone());
    let ctx = project::context_for_root(&project_root, harness_home).map_err(project_err)?;

    // Refuse to clobber a central store that already holds ledger data, unless
    // forced. A central store that only has metadata.json (freshly created) is fine.
    if central_store_has_ledger_rows(&ctx.store_root) && !force {
        return Err(CliError::Usage(format!(
            "central store {} already has data; refusing to overwrite (pass --force to merge-copy)",
            ctx.store_root.display()
        )));
    }

    let before = count_store_records(&local_store)?;
    std::fs::create_dir_all(&ctx.store_root)?;
    let copied = copy_store_contents(&local_store, &ctx.store_root)?;
    let after = count_store_records(&ctx.store_root)?;

    // Register the project, then pin identity in the central store with a
    // `migrated_from` breadcrumb. The metadata write comes AFTER
    // `register_and_activate` (which itself writes a `migrated_from`-less
    // metadata.json) so the breadcrumb is the one that survives.
    let now = now_string();
    let prev_active = project::active_project_id(harness_home).map_err(project_err)?;
    project::register_and_activate(harness_home, &project_root, &now).map_err(project_err)?;
    project::write_metadata(&ctx, Some(local_store.clone())).map_err(project_err)?;
    if !switch {
        // Non-disruptive by default: restore the previously active project (or clear
        // if none) so a bare `migrate` does not silently flip the active project.
        match prev_active {
            Some(prev) if prev != ctx.id => {
                project::switch_current_project(harness_home, &prev, &now).map_err(project_err)?;
            }
            None => {
                let mut registry =
                    project::ProjectRegistry::load(harness_home).map_err(project_err)?;
                registry.current_project_id = None;
                registry.save(harness_home).map_err(project_err)?;
                project::clear_active_project(harness_home).map_err(project_err)?;
            }
            _ => {}
        }
    }
    project::write_migrated_marker(&local_store, &ctx.store_root).map_err(project_err)?;

    print_json(&serde_json::json!({
        "migrated": true,
        "project_id": ctx.id,
        "from": local_store.display().to_string(),
        "to": ctx.store_root.display().to_string(),
        "files_copied": copied,
        "records_before": before,
        "records_after": after,
        "switched": switch,
    }))
}

/// Whether a central store already holds any `*.jsonl` ledger rows (used to guard
/// `migrate` against clobbering newer central data). A bare `metadata.json` does not
/// count as data.
fn central_store_has_ledger_rows(store_root: &Path) -> bool {
    count_store_records(store_root)
        .map(|n| n > 0)
        .unwrap_or(false)
}

/// Count total non-empty lines across every `*.jsonl` file in a store dir (the
/// record-count metric `migrate` reports before/after). Missing dir → 0.
fn count_store_records(store_root: &Path) -> CliResult<u64> {
    let mut total = 0u64;
    let read_dir = match std::fs::read_dir(store_root) {
        Ok(rd) => rd,
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(0),
        Err(e) => return Err(CliError::Io(e)),
    };
    for entry in read_dir.flatten() {
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) == Some("jsonl") {
            let text = std::fs::read_to_string(&path)?;
            total += text.lines().filter(|l| !l.trim().is_empty()).count() as u64;
        }
    }
    Ok(total)
}

/// Copy active `*.jsonl` ledgers and the `prompts/` / `runtimes/` payload dirs
/// from `src` into `dst`, preserving filenames. Returns the
/// number of top-level entries copied. Existing destination files are overwritten
/// (merge-copy under `--force`); missing source payload dirs are skipped.
fn copy_store_contents(src: &Path, dst: &Path) -> CliResult<u64> {
    let mut copied = 0u64;
    // 1. JSONL ledgers (flat files at the store root).
    for entry in std::fs::read_dir(src)?.flatten() {
        let path = entry.path();
        if path.extension().and_then(|e| e.to_str()) == Some("jsonl") {
            if let Some(name) = path.file_name() {
                if name == "provider_sessions.jsonl" {
                    continue;
                }
                std::fs::copy(&path, dst.join(name))?;
                copied += 1;
            }
        }
    }
    // 2. Payload directories (recursive).
    for dir in STORE_PAYLOAD_DIRS {
        let from = src.join(dir);
        if from.is_dir() {
            copy_dir_recursive(&from, &dst.join(dir))?;
            copied += 1;
        }
    }
    Ok(copied)
}

/// Recursively copy a directory tree (files + subdirs), creating `dst` as needed.
fn copy_dir_recursive(src: &Path, dst: &Path) -> CliResult<()> {
    std::fs::create_dir_all(dst)?;
    for entry in std::fs::read_dir(src)?.flatten() {
        let path = entry.path();
        let target = dst.join(entry.file_name());
        let file_type = entry.file_type()?;
        if file_type.is_dir() {
            copy_dir_recursive(&path, &target)?;
        } else if file_type.is_file() {
            std::fs::copy(&path, &target)?;
        }
        // Symlinks in a store are not expected; skip them rather than following.
    }
    Ok(())
}

/// Return a stable relative-file index without following symlinks.
fn directory_file_index(root: &Path) -> CliResult<Vec<PathBuf>> {
    fn visit(root: &Path, relative: &Path, out: &mut Vec<PathBuf>) -> CliResult<()> {
        let current = root.join(relative);
        for entry in std::fs::read_dir(current)?.flatten() {
            let file_type = entry.file_type()?;
            let next = relative.join(entry.file_name());
            if file_type.is_dir() {
                visit(root, &next, out)?;
            } else if file_type.is_file() {
                out.push(next);
            }
        }
        Ok(())
    }

    let mut files = Vec::new();
    visit(root, Path::new(""), &mut files)?;
    files.sort();
    Ok(files)
}

fn directory_trees_equal(left: &Path, right: &Path) -> CliResult<bool> {
    if !right.is_dir() {
        return Ok(false);
    }
    let left_files = directory_file_index(left)?;
    let right_files = directory_file_index(right)?;
    if left_files != right_files {
        return Ok(false);
    }
    for relative in left_files {
        if std::fs::read(left.join(&relative))? != std::fs::read(right.join(&relative))? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn run() -> CliResult<()> {
    let mut args: Vec<String> = env::args().skip(1).collect();
    // Optional debug flag: print which store was chosen and why (P7 "no silent
    // fallback"). Stripped before resolution so subcommands never see it.
    let store_source_debug = take_flag(&mut args, "--store-source");
    // `governance` is store-LESS: it gates a project's files (docs/skills) and
    // must run identically on any project — including a non-harness, no-node
    // repo — without resolving (or emitting deprecation noise about) a harness
    // store. Route it before `resolve_store` so it never touches the store.
    if args.first().map(String::as_str) == Some("governance") {
        return governance_command(&args[1..]);
    }
    // Legacy export is deliberately resolved outside the normal store fallback
    // chain. It requires one valid explicit project, wins over workflow-child
    // store guards, and never falls back to cwd/current/global when the selector
    // is invalid. Verification is fully offline and resolves no live store.
    if args.first().map(String::as_str) == Some("legacy-goal-task") {
        return legacy_goal_task_command(&mut args);
    }
    // `cheatsheet` is store-LESS: it prints operating knowledge for the Host
    // and must not require a store, project, or space.
    if args.first().map(String::as_str) == Some("cheatsheet") {
        return cheatsheet_command(&args[1..]);
    }
    // Resolve the store root FIRST (strips a global `--store`/`--project` from
    // `args` so the subcommand parsers never see them). `serve` and `run-script`
    // started from different working directories converge on ONE store via the
    // registry's current project (issue #89 item 3, now project-routed).
    let command = command_name_for_resolution(&args);
    let resolved = resolve_store(&mut args, command.as_deref())?;
    if store_source_debug {
        eprintln!(
            "store-source: {:?} root={}",
            resolved.source,
            resolved.root.display()
        );
        if let Some(company) = &resolved.company_context {
            eprintln!("company-context: id={} name={}", company.id, company.name);
        }
    }
    if args.is_empty() || args[0] == "help" || args[0] == "--help" {
        print_help();
        return Ok(());
    }

    let store = HarnessStore::new(resolved.root.clone());
    match args[0].as_str() {
        "init" => {
            init_routed(&store, &resolved)?;
        }
        "project" => project_command(&args[1..])?,
        "space" => execution_space_command(&args[1..])?,
        "agent" => agent_command(&store, resolved.context.as_ref(), &args[1..])?,
        "org" => org_command(&store, &args[1..])?,
        "team" => team_command(&store, &args[1..])?,
        "mission" => mission_command(&store, &args[1..])?,
        "wave" => wave_command(&store, &args[1..])?,
        "team-run" => team_run_command(&store, &resolved, &args[1..])?,
        "member-run" => member_run_command(&store, &args[1..])?,
        "member" => member_command(&store, &args[1..])?,
        "company" => company_command(&store, &args[1..])?,
        "dashboard" => dashboard_command(&store, &resolved, &args[1..])?,
        "workflow" => workflow_command(&store, resolved.context.as_ref(), &args[1..])?,
        "hook" => hook_command(&store, &args[1..])?,
        "serve" => serve_command(&store, &resolved, &args[1..])?,
        "mcp" => mcp::run(&store, &resolved)?,
        #[cfg(unix)]
        "daemon" => daemon_command(&store, &args[1..])?,
        command if retired_command(command) => return Err(retired_surface_error(command)),
        command => return Err(CliError::Usage(format!("unknown command: {command}"))),
    }
    Ok(())
}

fn retired_command(command: &str) -> bool {
    matches!(
        command,
        "goal"
            | "phase"
            | "task"
            | "proposal"
            | "git"
            | "review"
            | "gap"
            | "goal-design"
            | "goal-evaluation"
            | "goal-case"
            | "vision"
            | "decision"
            | "autonomy"
            | "board"
            | "codex"
    )
}

fn retired_surface_error(command: &str) -> CliError {
    CliError::Usage(format!(
        "`harness {command}` was retired with the Goal/GoalPhase/Task Graph coordination stack; use Mission/Wave plus agent-team, dynamic-workflow, or host execution. Historical data remains available only through `harness legacy-goal-task export|verify`."
    ))
}

fn company_command(store: &HarnessStore, args: &[String]) -> CliResult<()> {
    require_subcommand(args, "company <init|list|current|switch|show|migrate-from-project|migrations> | company docs ... | company work list|query|create|update|assign|transition|close|milestone | company org ... | company approval ... | company finance ... | company gateway social readiness")?;
    match args[0].as_str() {
        "init" => company_store_init_command(args.get(1..).unwrap_or(&[])),
        "list" => company_store_list_command(),
        "current" => company_store_current_command(),
        "switch" => company_store_switch_command(args.get(1..).unwrap_or(&[])),
        "show" => company_store_show_command(args.get(1..).unwrap_or(&[])),
        "migrate-from-project" => {
            company_store_migrate_from_project_command(args.get(1..).unwrap_or(&[]))
        }
        "migrations" => company_store_migrations_command(store),
        "docs" => company_docs_command(store, &args[1..]),
        "work" => company_work_command(store, &args[1..]),
        "org" => company_org_command(store, &args[1..]),
        "approval" => company_approval_command(store, &args[1..]),
        "finance" => company_finance_command(store, &args[1..]),
        "gateway" => company_gateway_command(&args[1..]),
        other => Err(CliError::Usage(format!(
            "unknown company command: {other}; usage: harness company <init|list|current|switch|show|migrate-from-project|migrations> | harness company docs ... | harness company work ... | harness company org ... | harness company approval ... | harness company finance ... | harness company gateway ..."
        ))),
    }
}

fn company_gateway_command(args: &[String]) -> CliResult<()> {
    require_subcommand(args, "company gateway social readiness")?;
    match args[0].as_str() {
        "social" => {
            require_subcommand(&args[1..], "company gateway social readiness")?;
            match args[1].as_str() {
                "readiness" => company_gateway_social_readiness_command(&args[2..]),
                other => Err(CliError::Usage(format!(
                    "unknown company gateway social command: {other}; usage: harness company gateway social readiness"
                ))),
            }
        }
        other => Err(CliError::Usage(format!(
            "unknown company gateway command: {other}; usage: harness company gateway social readiness"
        ))),
    }
}

fn company_gateway_social_readiness_command(args: &[String]) -> CliResult<()> {
    let requested = many(args, "--platform");
    let platforms = if requested.is_empty() {
        vec![
            "xiaohongshu".to_string(),
            "douyin".to_string(),
            "wechat_channels".to_string(),
        ]
    } else {
        requested
    };
    let adb = value(args, "--adb").unwrap_or_else(|| "adb".to_string());
    let device = value(args, "--device");
    let mut base_args: Vec<String> = Vec::new();
    if let Some(device) = &device {
        base_args.push("-s".to_string());
        base_args.push(device.clone());
    }

    let devices = match run_command_text(&adb, &["devices".to_string(), "-l".to_string()]) {
        Ok(output) => output,
        Err(error) => {
            return print_json(&serde_json::json!({
                "ok": true,
                "command": "harness company gateway social readiness",
                "gateway": "social_content",
                "status": "adb_unavailable",
                "error": error.to_string(),
                "boundaries": social_gateway_readiness_boundaries(),
                "platforms": platform_readiness_without_device(&platforms),
            }));
        }
    };
    if !android_devices_has_authorized_device(&devices) {
        return print_json(&serde_json::json!({
            "ok": true,
            "command": "harness company gateway social readiness",
            "gateway": "social_content",
            "status": "no_authorized_android_device",
            "adb_devices": devices,
            "boundaries": social_gateway_readiness_boundaries(),
            "platforms": platform_readiness_without_device(&platforms),
        }));
    }

    let mut pm_args = base_args.clone();
    pm_args.extend([
        "shell".to_string(),
        "pm".to_string(),
        "list".to_string(),
        "packages".to_string(),
    ]);
    let packages = run_command_text(&adb, &pm_args)?;
    let mut focus_args = base_args;
    focus_args.extend([
        "shell".to_string(),
        "dumpsys".to_string(),
        "window".to_string(),
    ]);
    let focus = run_command_text(&adb, &focus_args).unwrap_or_default();
    let results: Vec<serde_json::Value> = platforms
        .iter()
        .map(|platform| social_platform_readiness(platform, &packages, &focus))
        .collect();

    print_json(&serde_json::json!({
        "ok": true,
        "command": "harness company gateway social readiness",
        "gateway": "social_content",
        "status": "observed",
        "device_selector": device,
        "boundaries": social_gateway_readiness_boundaries(),
        "platforms": results,
    }))
}

fn run_command_text(program: &str, args: &[String]) -> CliResult<String> {
    let output = Command::new(program).args(args).output()?;
    let mut text = String::from_utf8_lossy(&output.stdout).to_string();
    if text.trim().is_empty() && !output.stderr.is_empty() {
        text = String::from_utf8_lossy(&output.stderr).to_string();
    }
    if !output.status.success() {
        return Err(CliError::Usage(format!(
            "{program} {} failed: {}",
            args.join(" "),
            text.trim()
        )));
    }
    Ok(text)
}

fn android_devices_has_authorized_device(devices: &str) -> bool {
    devices
        .lines()
        .filter(|line| !line.starts_with("List of devices"))
        .any(|line| line.split_whitespace().nth(1) == Some("device"))
}

fn platform_readiness_without_device(platforms: &[String]) -> Vec<serde_json::Value> {
    platforms
        .iter()
        .map(|platform| {
            let (canonical, package, display) = social_platform_package(platform);
            serde_json::json!({
                "platform": canonical,
                "display_name": display,
                "package": package,
                "readiness_state": "unknown_no_device",
                "installed": false,
                "focused": false,
            })
        })
        .collect()
}

fn social_platform_readiness(platform: &str, packages: &str, focus: &str) -> serde_json::Value {
    let (canonical, package, display) = social_platform_package(platform);
    let known = !package.is_empty();
    let installed = known
        && packages
            .lines()
            .any(|line| line.trim() == format!("package:{package}"));
    let focused = known && current_android_focus_package(focus).as_deref() == Some(package);
    let readiness_state = if !known {
        "unknown_platform"
    } else if installed && focused {
        "installed_currently_focused"
    } else if installed {
        "installed_not_focused"
    } else {
        "not_installed_or_not_detected"
    };
    serde_json::json!({
        "platform": canonical,
        "display_name": display,
        "package": package,
        "installed": installed,
        "focused": focused,
        "readiness_state": readiness_state,
        "recommended_record_type": "social_platform_account",
        "recommended_human_gates": [
            "login",
            "publish",
            "delete",
            "paid_promotion",
            "account_settings",
            "private_message_export"
        ],
        "recommended_allowed_automation": [
            "open_app",
            "screenshot",
            "draft_preparation",
            "visible_metric_read"
        ]
    })
}

fn current_android_focus_package(window_dump: &str) -> Option<String> {
    window_dump
        .lines()
        .find(|line| line.contains("mCurrentFocus="))
        .and_then(|line| {
            let activity = line
                .split_whitespace()
                .find(|part| part.contains('/') && !part.starts_with("Window{"))?;
            activity
                .split_once('/')
                .map(|(package, _)| package.trim().to_string())
        })
        .filter(|package| !package.is_empty())
}

fn social_platform_package(platform: &str) -> (&'static str, &'static str, &'static str) {
    match platform {
        "xhs" | "xiaohongshu" | "rednote" => ("xiaohongshu", "com.xingin.xhs", "Xiaohongshu"),
        "douyin" | "aweme" => ("douyin", "com.ss.android.ugc.aweme", "Douyin"),
        "wechat" | "wechat_channels" | "channels" | "shipinhao" => {
            ("wechat_channels", "com.tencent.mm", "WeChat Channels")
        }
        _ => ("unknown", "", "Unknown platform"),
    }
}

fn social_gateway_readiness_boundaries() -> serde_json::Value {
    serde_json::json!({
        "read_only": true,
        "store_side_effects": false,
        "publishing_side_effects": false,
        "login_side_effects": false,
        "payment_side_effects": false,
        "deletion_side_effects": false,
        "credential_export": false,
        "output_role": "observation_for_social_platform_account_typed_records_and_WorkItems"
    })
}

fn company_store_init_command(args: &[String]) -> CliResult<()> {
    let id = required(args, "--id")?;
    let name = value(args, "--name").unwrap_or_else(|| id.clone());
    let harness_home = company_store::harness_home().map_err(company_store_err)?;
    let ctx = company_store::register_and_activate(&harness_home, &id, &name, &now_string())
        .map_err(company_store_err)?;
    HarnessStore::new(ctx.store_root.clone()).init()?;
    print_json(&company_context_json(&ctx, &ctx.id))
}

fn company_store_list_command() -> CliResult<()> {
    let harness_home = company_store::harness_home().map_err(company_store_err)?;
    let current = company_store::active_company_id(&harness_home)
        .map_err(company_store_err)?
        .unwrap_or_default();
    let companies = company_store::list_companies(&harness_home).map_err(company_store_err)?;
    let json: Vec<serde_json::Value> = companies
        .iter()
        .map(|ctx| company_context_json(ctx, &current))
        .collect();
    print_json(&json)
}

fn company_store_current_command() -> CliResult<()> {
    let harness_home = company_store::harness_home().map_err(company_store_err)?;
    match company_store::active_company_id(&harness_home).map_err(company_store_err)? {
        Some(id) => {
            match company_store::context_for_id(&harness_home, &id).map_err(company_store_err)? {
                Some(ctx) => print_json(&company_context_json(&ctx, &id)),
                None => print_json(&serde_json::json!({ "id": id, "is_current": true })),
            }
        }
        None => print_json(&serde_json::json!({
            "id": serde_json::Value::Null,
            "is_current": false,
        })),
    }
}

fn company_store_switch_command(args: &[String]) -> CliResult<()> {
    let id = args
        .iter()
        .find(|a| !a.starts_with("--"))
        .cloned()
        .ok_or_else(|| CliError::Usage("usage: harness company switch <id>".to_string()))?;
    let harness_home = company_store::harness_home().map_err(company_store_err)?;
    let ctx = company_store::switch_current_company(&harness_home, &id, &now_string())
        .map_err(company_store_err)?;
    print_json(&company_context_json(&ctx, &ctx.id))
}

fn company_store_show_command(args: &[String]) -> CliResult<()> {
    let harness_home = company_store::harness_home().map_err(company_store_err)?;
    let selector = args.iter().find(|a| !a.starts_with("--")).cloned();
    let current = company_store::active_company_id(&harness_home)
        .map_err(company_store_err)?
        .unwrap_or_default();
    let id = match selector {
        Some(id) => id,
        None => return company_store_current_command(),
    };
    let ctx = company_store::context_for_id(&harness_home, &id)
        .map_err(company_store_err)?
        .ok_or_else(|| CliError::Usage(format!("unknown company: {id}")))?;
    print_json(&company_context_json(&ctx, &current))
}

fn company_store_migrate_from_project_command(args: &[String]) -> CliResult<()> {
    let from_project = required(args, "--from-project")?;
    let id = required(args, "--id")?;
    let name = value(args, "--name").unwrap_or_else(|| id.clone());
    let force = has_flag(args, "--force");
    let verify_only = has_flag(args, "--verify-only");
    let harness_home = company_store::harness_home().map_err(company_store_err)?;
    let source_project =
        resolve_project_selector(&harness_home, &from_project).ok_or_else(|| {
            CliError::Usage(format!(
                "unknown source project: {from_project}; pass a registered project id or path"
            ))
        })?;
    let ctx = if verify_only {
        company_store::context_for_id(&harness_home, &id)
            .map_err(company_store_err)?
            .ok_or_else(|| {
                CliError::Usage(format!(
                    "Company Store {id} does not exist; run migrate-from-project without --verify-only first"
                ))
            })?
    } else {
        company_store::register_and_activate(&harness_home, &id, &name, &now_string())
            .map_err(company_store_err)?
    };
    let outcome = if verify_only {
        CompanyLedgerCopyOutcome::default()
    } else {
        copy_company_os_ledgers(&source_project.store_root, &ctx.store_root, force).map_err(
            |err| {
                CliError::Usage(format!(
                    "Company Store migration refused from {} to {}: {err}",
                    source_project.store_root.display(),
                    ctx.store_root.display()
                ))
            },
        )?
    };
    HarnessStore::new(ctx.store_root.clone()).init()?;
    let verified_at = now_string();
    let verification =
        verify_company_os_ledger_migration(&source_project.store_root, &ctx.store_root).map_err(
            |err| {
                CliError::Usage(format!(
                    "Company Store migration verification failed from {} to {}: {err}",
                    source_project.store_root.display(),
                    ctx.store_root.display()
                ))
            },
        )?;
    let migration_record = serde_json::json!({
        "id": generated_id("company-store-migration"),
        "company_id": ctx.id,
        "source_project_id": source_project.id,
        "source_store_root": source_project.store_root.display().to_string(),
        "target_store_root": ctx.store_root.display().to_string(),
        "mode": if verify_only { "verify_only" } else { "copy_and_verify" },
        "verified_at": verified_at,
        "verification": verification,
        "boundary": {
            "copied": "company_os_*.jsonl only",
            "execution_space_migration": false,
            "project_binding_migration": false,
            "dual_write": false,
            "destructive_delete": false,
            "source_access": "read_only_audit_recommended",
            "source_read_only_enforced": false
        }
    });
    append_jsonl_value(
        &ctx.store_root.join("company_store_migrations.jsonl"),
        &migration_record,
    )?;
    let source_marker = serde_json::json!({
        "company_id": ctx.id,
        "target_store_root": ctx.store_root.display().to_string(),
        "source_project_id": source_project.id,
        "verified_at": verified_at,
        "status": "migrated_and_verified",
        "recommended_access": "read_only_audit",
        "read_only_enforced": false,
        "destructive_delete": false,
        "dual_write": false
    });
    fs::write(
        source_project
            .store_root
            .join("COMPANY_OS_MIGRATED_TO_COMPANY.json"),
        serde_json::to_string_pretty(&source_marker)?,
    )?;
    print_json(&serde_json::json!({
        "ok": true,
        "command": "harness company migrate-from-project",
        "mode": if verify_only { "verify_only" } else { "copy_and_verify" },
        "company": company_context_json(&ctx, &ctx.id),
        "source_project": project_context_json(&source_project, ""),
        "copied_files": outcome.copied_files,
        "copied_records": outcome.copied_records,
        "skipped_identical_files": outcome.skipped_identical_files,
        "verification": migration_record["verification"],
        "migration_record": migration_record,
        "source_marker": source_marker,
        "boundary": {
            "copied": "company_os_*.jsonl only",
            "not_copied": ["missions.jsonl", "waves.jsonl", "agent_teams.jsonl", "team_runs.jsonl", "member_runs.jsonl", "team_messages.jsonl", "provider_sessions.jsonl", "runtimes", "prompts"],
            "execution_space_migration": false,
            "project_binding_migration": false,
            "dual_write": false,
            "destructive_delete": false
        },
        "next_commands": [
            format!("harness --company {} company docs health", ctx.id),
            format!("harness --company {} company work list", ctx.id),
            format!("harness --company {} company org list", ctx.id)
        ]
    }))
}

fn company_store_migrations_command(store: &HarnessStore) -> CliResult<()> {
    let path = store.root().join("company_store_migrations.jsonl");
    let records = match fs::read_to_string(path) {
        Ok(text) => text
            .lines()
            .filter(|line| !line.trim().is_empty())
            .map(serde_json::from_str)
            .collect::<Result<Vec<serde_json::Value>, _>>()?,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Vec::new(),
        Err(error) => return Err(CliError::Io(error)),
    };
    print_json(&serde_json::json!({
        "command": "harness company migrations",
        "records": records
    }))
}

#[derive(Debug, Clone, Default)]
struct CompanyLedgerCopyOutcome {
    copied_files: u64,
    copied_records: u64,
    skipped_identical_files: u64,
}

fn verify_company_os_ledger_migration(src: &Path, dst: &Path) -> Result<serde_json::Value, String> {
    let mut source_ledgers = fs::read_dir(src)
        .map_err(|error| error.to_string())?
        .filter_map(Result::ok)
        .map(|entry| entry.path())
        .filter(|path| {
            path.file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| name.starts_with("company_os_") && name.ends_with(".jsonl"))
        })
        .collect::<Vec<_>>();
    source_ledgers.sort();
    if source_ledgers.is_empty() {
        return Err(format!(
            "source store has no company_os_*.jsonl ledgers: {}",
            src.display()
        ));
    }
    let forbidden_execution_files = [
        "missions.jsonl",
        "waves.jsonl",
        "agent_teams.jsonl",
        "team_runs.jsonl",
        "member_runs.jsonl",
        "team_messages.jsonl",
        "provider_sessions.jsonl",
    ];
    let leaked_execution_files = forbidden_execution_files
        .iter()
        .filter(|file| dst.join(file).exists())
        .copied()
        .collect::<Vec<_>>();
    if !leaked_execution_files.is_empty() {
        return Err(format!(
            "target Company Store contains execution ledgers: {}",
            leaked_execution_files.join(", ")
        ));
    }
    let mut file_results = Vec::new();
    let mut source_records = 0_u64;
    let mut target_records = 0_u64;
    for source_path in source_ledgers {
        let file_name = source_path
            .file_name()
            .and_then(|name| name.to_str())
            .ok_or_else(|| "source ledger has a non-UTF-8 filename".to_string())?;
        let target_path = dst.join(file_name);
        if !target_path.is_file() {
            return Err(format!(
                "target ledger is missing: {}",
                target_path.display()
            ));
        }
        let source_text = fs::read_to_string(&source_path).map_err(|error| error.to_string())?;
        let target_text = fs::read_to_string(&target_path).map_err(|error| error.to_string())?;
        let source_lines = source_text
            .lines()
            .filter(|line| !line.trim().is_empty())
            .collect::<Vec<_>>();
        let target_lines = target_text
            .lines()
            .filter(|line| !line.trim().is_empty())
            .collect::<HashSet<_>>();
        let missing_source_records = source_lines
            .iter()
            .filter(|line| !target_lines.contains(**line))
            .count();
        if missing_source_records > 0 {
            return Err(format!(
                "target ledger {file_name} is missing {missing_source_records} exact source record(s)"
            ));
        }
        source_records += source_lines.len() as u64;
        target_records += target_lines.len() as u64;
        file_results.push(serde_json::json!({
            "file": file_name,
            "source_records": source_lines.len(),
            "target_records": target_lines.len(),
            "missing_source_records": 0,
            "source_content_hash": content_hash_hex16(&source_text)
        }));
    }
    Ok(serde_json::json!({
        "status": "verified",
        "verified_files": file_results.len(),
        "source_records": source_records,
        "target_records": target_records,
        "missing_source_records": 0,
        "execution_ledgers_in_target": [],
        "files": file_results
    }))
}

fn append_jsonl_value(path: &Path, value: &serde_json::Value) -> CliResult<()> {
    let mut file = fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(path)?;
    serde_json::to_writer(&mut file, value)?;
    file.write_all(b"\n")?;
    file.flush()?;
    Ok(())
}

fn copy_company_os_ledgers(
    src: &Path,
    dst: &Path,
    force: bool,
) -> Result<CompanyLedgerCopyOutcome, String> {
    if !src.is_dir() {
        return Err(format!("source store is missing: {}", src.display()));
    }
    fs::create_dir_all(dst).map_err(|err| err.to_string())?;
    let mut outcome = CompanyLedgerCopyOutcome::default();
    let mut saw_company_ledger = false;
    for entry in fs::read_dir(src).map_err(|err| err.to_string())? {
        let entry = entry.map_err(|err| err.to_string())?;
        let path = entry.path();
        let Some(file_name) = path.file_name().and_then(|name| name.to_str()) else {
            continue;
        };
        if !file_name.starts_with("company_os_") || !file_name.ends_with(".jsonl") {
            continue;
        }
        saw_company_ledger = true;
        let target = dst.join(file_name);
        if target.exists() {
            let src_bytes = fs::read(&path).map_err(|err| err.to_string())?;
            let dst_bytes = fs::read(&target).map_err(|err| err.to_string())?;
            if src_bytes == dst_bytes {
                outcome.skipped_identical_files += 1;
                outcome.copied_records +=
                    count_non_empty_lines(&path).map_err(|e| e.to_string())?;
                continue;
            }
            if !force {
                return Err(format!(
                    "target ledger already exists with different content: {} (pass --force to overwrite Company OS ledgers only)",
                    target.display()
                ));
            }
        }
        fs::copy(&path, &target).map_err(|err| err.to_string())?;
        outcome.copied_files += 1;
        outcome.copied_records += count_non_empty_lines(&path).map_err(|e| e.to_string())?;
    }
    if !saw_company_ledger {
        return Err(format!(
            "source store has no company_os_*.jsonl ledgers: {}",
            src.display()
        ));
    }
    Ok(outcome)
}

fn count_non_empty_lines(path: &Path) -> std::io::Result<u64> {
    let text = fs::read_to_string(path)?;
    Ok(text.lines().filter(|line| !line.trim().is_empty()).count() as u64)
}

fn company_context_json(ctx: &company_store::CompanyContext, current: &str) -> serde_json::Value {
    serde_json::json!({
        "id": ctx.id,
        "name": ctx.name,
        "store_root": ctx.store_root.display().to_string(),
        "is_current": ctx.id == current,
        "identity_boundary": "company_store",
        "execution_dependency": "optional",
        "project_binding": "external",
    })
}

fn company_org_command(store: &HarnessStore, args: &[String]) -> CliResult<()> {
    require_subcommand(
        args,
        "company org actor|unit|membership | list|query|create-human|create-agent|create-unit|add-membership|transition-actor|update-permissions|link-execution|unlink-execution",
    )?;
    match args[0].as_str() {
        "actor" => company_org_actor_command(store, &args[1..]),
        "unit" => company_org_unit_command(store, &args[1..]),
        "membership" => company_org_membership_command(store, &args[1..]),
        "list" => company_org_list_command(store, &args[1..]),
        "query" => company_org_query_command(store, &args[1..]),
        "create-human" => company_org_create_human_command(store, &args[1..]),
        "create-agent" => company_org_create_agent_command(store, &args[1..]),
        "create-unit" => company_org_create_unit_command(store, &args[1..]),
        "add-membership" => company_org_add_membership_command(store, &args[1..]),
        "transition-actor" => company_org_transition_actor_command(store, &args[1..]),
        "update-permissions" => company_org_update_permissions_command(store, &args[1..]),
        "link-execution" => company_org_link_execution_command(store, &args[1..]),
        "unlink-execution" => company_org_unlink_execution_command(store, &args[1..]),
        other => Err(CliError::Usage(format!(
            "unknown company org command: {other}; usage: harness company org actor|unit|membership | list|query|create-human|create-agent|create-unit|add-membership|transition-actor|update-permissions|link-execution|unlink-execution"
        ))),
    }
}

fn company_org_list_command(store: &HarnessStore, args: &[String]) -> CliResult<()> {
    let actor_kind = value(args, "--actor-kind");
    let status = value(args, "--status");
    let unit_id = value(args, "--unit");
    let memberships = store.latest_organization_memberships()?;
    let actors = store
        .latest_actors()?
        .into_iter()
        .filter_map(|actor| serde_json::to_value(actor).ok())
        .filter(|actor| {
            actor_kind.as_deref().is_none_or(|kind| {
                actor.get("actor_type").and_then(serde_json::Value::as_str) == Some(kind)
            })
        })
        .filter(|actor| {
            status.as_deref().is_none_or(|expected| {
                actor
                    .get("actor")
                    .and_then(|record| record.get("status"))
                    .and_then(serde_json::Value::as_str)
                    == Some(expected)
            })
        })
        .filter(|actor| {
            unit_id.as_deref().is_none_or(|unit| {
                let Some(kind) = actor.get("actor_type").and_then(serde_json::Value::as_str) else {
                    return false;
                };
                let Some(id) = actor
                    .get("actor")
                    .and_then(|record| record.get("id"))
                    .and_then(serde_json::Value::as_str)
                else {
                    return false;
                };
                memberships.iter().any(|membership| {
                    serde_json::to_value(membership)
                        .ok()
                        .is_some_and(|membership| {
                            membership
                                .get("org_unit_id")
                                .and_then(serde_json::Value::as_str)
                                == Some(unit)
                                && membership.get("status").and_then(serde_json::Value::as_str)
                                    == Some("active")
                                && membership
                                    .get("actor_ref")
                                    .and_then(|actor| actor.get("actor_type"))
                                    .and_then(serde_json::Value::as_str)
                                    == Some(kind)
                                && membership
                                    .get("actor_ref")
                                    .and_then(|actor| actor.get("actor_id"))
                                    .and_then(serde_json::Value::as_str)
                                    == Some(id)
                        })
                })
            })
        })
        .collect::<Vec<_>>();
    let org_units = store.latest_org_units()?;
    print_json(&serde_json::json!({
        "ok": true,
        "command": "harness company org list",
        "result": {
            "actors": actors,
            "org_units": org_units,
            "memberships": memberships,
            "summary": {
                "actor_count": actors.len(),
                "org_unit_count": org_units.len(),
                "membership_count": memberships.len()
            },
            "boundaries": company_org_boundaries()
        }
    }))
}

fn company_org_query_command(store: &HarnessStore, args: &[String]) -> CliResult<()> {
    let actor_id = value(args, "--actor");
    let unit_id = value(args, "--unit");
    let membership_id = value(args, "--membership");
    if actor_id.is_none() && unit_id.is_none() && membership_id.is_none() {
        return Err(CliError::Usage(
            "usage: harness company org query --actor <id> [--actor-kind <kind>] | --unit <id> | --membership <id>".into(),
        ));
    }
    let actor = actor_id
        .as_deref()
        .map(|id| {
            let kind = value(args, "--actor-kind").unwrap_or_else(|| "agent".to_string());
            latest_company_actor_value(store, &kind, id)
        })
        .transpose()?;
    let unit = unit_id
        .as_deref()
        .map(|id| latest_org_unit_value(store, id))
        .transpose()?;
    let membership = membership_id
        .as_deref()
        .map(|id| latest_membership_value(store, id))
        .transpose()?;
    let related_memberships = store
        .latest_organization_memberships()?
        .into_iter()
        .filter(|candidate| {
            actor_id
                .as_deref()
                .is_some_and(|id| candidate.actor_ref.actor_id == id)
                || unit_id
                    .as_deref()
                    .is_some_and(|id| candidate.org_unit_id == id)
                || membership_id
                    .as_deref()
                    .is_some_and(|id| candidate.id == id)
        })
        .collect::<Vec<_>>();
    print_json(&serde_json::json!({
        "ok": true,
        "command": "harness company org query",
        "result": {
            "actor": actor,
            "org_unit": unit,
            "membership": membership,
            "related_memberships": related_memberships,
            "boundaries": company_org_boundaries()
        }
    }))
}

